INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65815327', 65815327, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS13 LAPAS KELAS II B PURWODADI', 'Pengadaan Pemeliharaan Gedung dan Bangunan Tidak Bertingkat pada Lembaga Pemasyarakatan Kelas IIB Purwodadi - Jawa Tengah Tahun Anggaran 2026', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Tengah, Grobogan (Kab.)', 199519200, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 10718, m2, @ 81000 )', '1. Pemeliharaan Gedung dan Bangunan Tidak Bertingkat ( 10718, m2, @ 81000 ); A. Pekerjaan Persiapan B. Pekerjaan SMK3 (Sistem Manajemen Keselamatan Konstruksi) C. Pekerjaan Renovasi Pagar', '1. Pemeliharaan Gedung dan Bangunan Tidak Bertingkat ( 10718, m2, @ 81000 ); A. Pekerjaan Persiapan • Pemasangan papan nama proyek sebagai bentuk transparansi. • Pembersihan lokasi pada awal dan akhir pekerjaan. • Mobilisasi dan demobilisasi peralatan serta material. B. Pekerjaan SMK3 (Sistem Manajemen Keselamatan Konstruksi) Mengingat pekerjaan dilakukan di lingkungan sensitif, penerapan SMK3 sangat diwajibkan, meliputi: • Penyusunan pelaporan dan pengarahan keselamatan konstruksi. • Penyediaan Alat Pelindung Diri (APD) bagi pekerja (Helm, pelindung mata, sarung tangan, sepatu keselamatan, rompi, dan masker). • Pemasangan rambu-rambu petunjuk, larangan, peringatan, dan informasi di area kerja. • Penyediaan peralatan P3K dan lampu darurat. C. Pekerjaan Renovasi Pagar Ini merupakan inti dari kegiatan rehabilitasi, yang mencakup: 1. Bongkaran: Pembersihan kawat berduri eksisting 2. Struktur Besi: Pemasangan rangka vertikal dan horizontal menggunakan besi siku 3. Pengamanan Tambahan: Pemasangan rangka Y sebagai penyangga dan pemasangan kawat duri silet (razor wire) 4. Expanded Mesh: Pemasangan panel expanded mesh pada pagar utama dan area pos untuk mencegah akses ilegal. 5. Finishing: Pengecatan seluruh bidang besi untuk melindungi material dari korosi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2390073);
