INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65852599', 65852599, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '000001 FOLU NET SINK 2030 RBC 1', 'Perencanaan Modifikasi Open Area Menjadi Shaded Area', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sulawesi Utara, Bitung (Kota)', 19000000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'Perencanaan Modifikasi Open Area menjadi Shaded Area yang berlokasi di Persemaian Likupang Batuputih, Kecamatan Ranowulu, Kota Bitung, Provinsi Sulawesi Utara', 'Persemaian Likupang Batuputih secara geografis berada di dekat pantai dengan jarak sekitar 800 meter dari laut dengan cuaca yang panas dan berangin menjadi salah satu penciri utama lokasi ini. Mengingat cuaca yang panas berlebihan di persemaian ini, penggunaan open area sebagai tempat pemeliharaan bibit kurang optimal. Untuk mengoptimalkan penggunaan open area perlu dimodifikasi menjadi shaded area. Persemaian Likupang Batuputih memiliki 40 petak yang terdiri atas 23 shaded area dan 17 open area. Saat ini yang digunakan sebagai tempat pemeliharaan bibit adalah pada shaded area. Sedangkan untuk open area tidak digunakan karena cuaca panas yang berlebihan dapat menyebabkan tanaman mati. Untuk itu perlu modifikasi open area menjadi shaded area. Spesifikasi pekerjaan adalah sebagai berikut : Tenaga-tenaga yang dibutuhkan dalam kegiatan perencanaan minimal terdiri atas: No KEAHLIAN JML (org) KUALIFIKASI A TENAGA AHLI 1 Ahli Arsitektur 1 S1 Arsitektur SKA Ahli Muda Pengalaman ≥ 3 Tahun B TENAGA PENDUKUNG 1 Surveyor 1 D3 Teknik Sipil SKK Juru Ukur 2 CAD/Drafter Autocad 1 D3, Teknik Sipil SKK Juru Gambar/ Draftman Persyaratan lain yang harus dilengkapi: Team leader/ketua tim dan tenaga ahli dilengkapi dengan: daftar riwayat hidup, FC Ijasah, FC NPWP, FC SKA, identitas diri dan bukti referensi kerja pengalaman perencanaan bangunan gedung atau sesuai dengan bidang keahliannya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2390476);
