INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65856681', 65856681, 'analyze_legacy', 'Kab. Wonogiri', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Belanja Jasa Tenaga Pelayanan Umum Operator Layanan Operasional Sub Kegiatan Optimalisasi Instalasi Pengolahan Lumpur Tinja (IPLT) pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Wonogiri', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Wonogiri (Kab.)', 16812000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Jasa Tenaga Pelayanan Umum Operator Layanan Operasional Sub Kegiatan Optimalisasi Instalasi Pengolahan Lumpur Tinja (IPLT) pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Wonogiri', '1. Dalam rangka menjamin berfungsinya Instalasi Pengolahan Lumpur Tinja (IPLT) secara optimal, berkelanjutan, dan sesuai dengan standar sanitasi aman, diperlukan tenaga pelayanan umum yang dapat melaksanakan kegiatan operasional, pemeliharaan, dan pengelolaan IPLT. Tenaga ini berperan penting dalam pengolahan lumpur tinja , mulai dari penyedotan di rumah warga sampai memastikan lumpur tinja yang masuk ke IPLT diolah secara aman, tidak mencemari lingkungan, serta memenuhi ketentuan teknis dan peraturan perundangan. Penyedia jasa dapat bekerja sebagai Tenaga Non ASN Operator Layanan Operasional, Tenaga Pengelola Instalasi Pengolahan Lumpur Tinja (IPLT) pada Bidang Cipta Karya Dinas Pekerjaan Umum dan Penataan Ruang . 2. Secara lebih rinci, tugas dan fungsi Tenaga Non ASN Operator Layanan Operasional ,Tenaga Pengelola Instalasi Pengolahan Lumpur Tinja (IPLT) pada Bidang Cipta Karya Dinas Pekerjaan Umum dan Penataan Ruang meliputi : 1. Pelayanan Penyedotan di Rumah Warga 1) Mendatangi lokasi tangki septik warga sesuai jadwal atau permintaan. 2) Mengoperasikan pompa dan selang truk tinja 3) Melakukan penyedotan lumpur tinja secara higienis 4) Memastikan tidak terjadi tumpahan atau pencemaran. 2. Pengangkutan Lumpur Tinja 1) Mengangkut lumpur tinja menuju Instalasi Pengolahan Lumpur Tinja (IPLT). 2) Menutup dan mengamankan tangki truk tinja selama perjalanan. 3. Penerimaan dan Pengolahan di IPLT 1) Membongkar lumpur tinja di bak penerima. 2) Mengoperasikan unit-unit proses IPLT (pengeringan lumpur, kolam pengolahan, dll). 3) Mengatur alur proses agar memenuhi standar pengolahan. 4. Pemeliharaan Sarana dan Prasarana 1) Membersihkan truk tinja, selang, dan peralatan. 2) Membersihkan area Instalasi Pengolahan Lumpur Tinja (IPLT). 3) Melakukan perawatan rutin dan melaporkan kerusakan. 5. Pengawasan di lapangan 1) Melakukan pengawasan terhadap pelaksanaan kegiatan di lapangan. 2) Memastikan kegiatan dilaksanakan sesuai dengan rencana teknis dan standar yang berlaku. 3) Memberikan masukan dan rekomendasi untuk perbaikan pelaksanaan kegiatan. 6. Fungsi Lainnya: 1) Melaksanakan tugas lain yang diberikan oleh atasan terkait dengan Pengelolaan Instalasi Pengolahan Lumpur Tinja. 2) Meningkatkan kapasitas diri melalui pendidikan dan pelatihan yang relevan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2390836);
