INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65817605', 65817605, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Pemeliharaan Gedung/Bangunan Kantor Bertingkat DJKI (jakarta) Berupa Pekerjaan Ruang Direktur TI lantai 9 Pada Ditjen Kekayaan Intelektual - DK Jakarta TA 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 120000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kelengkapan sarana dan sarana serta keindahan pada suatu gedung atau bangunan sangat mempengaruhi semangat seluruh pegawai dan dapat meningkatkan rasa nyaman serta tetap fokus dalam melaksanakan tugas dalam pekerjaan. Maka dipandang perlu adanya pemeliharaan khususnya untuk pemanfaatan gedung/bangunan demi menunjang kinerja pegawai di Direktorat Jenderal Kekayaan Intelektual sangat perlu. Pekerjaan yang dilakukan adalah Pengadaan pemeliharaan gedung/bangunan kantor bertingkat Djki (jakarta) berupa pekerjaan Pengadaan pemeliharaan gedung/bangunan kantor bertingkat Djki (jakarta) berupa pekerjaan Ruang Direktur TI lantai 9 Direktorat Jenderal Kekayaan Intelektual DK Jakarta T.A 2026. Kegiatan tersebut sangat perlu dilakukan untuk kelengkapan serta perbaikan sarana dan prasarana di gedung tersebut.', 'A PEKERJAAN BONGKAR 1 Pekerjaan Bongkar dinding Partis Gypsum : 17 m2 2 Pekerjaan Bongkar Plafon : 6 m2 3 Pekerjaan Bongkar lantai karpet : 20 m2 B PEKERJAAN PASANG 1 Pekerjaan Pasang dinding Partisi gypsum 2 muka dengan rangka besi holow : 17 m2 2 Pekerjaan Pasang plafon gypsum rangka besi holow : 6 m2 3 Pekerjaan Pengecatan dinding ex Dulux : 74,4 m2 4 Pekerjaan Pengecatan Plafon : 6 m2 5 Pekerjaan Pasang Lantai vinyl tebal 3mm : 38,08 m2 6 Pekerjaan coating lantai vinyl : 38,08 m2 7 Pekerjaan pasang pintu ex bongkaran : 1 unit 8 Pekerjaan Pasang Dipan uk 200x120cm : 1 unit 9 Pekerjaan Pasang Bed ( kasur ) : 1 set 10 Pekerjaan pasang lemari kayu finish pvc sheet uk. 80x200cm : 1 unit 11 Pekerjaan pasang Meja makan kayu set kursi : 1 set C PEKERJAAN PERAPIHAN 1 Pekerjaan Perapihan , pemindahan karpet ke lantai Basement : 1 Ls', 120000000, 'absurd', 'Terdapat pengadaan elemen yang menyerupai fasilitas hunian/pribadi di ruang direktur kantor, seperti dipan, kasur, lemari, dan meja makan set kursi. Untuk konteks pemeliharaan ruang kerja pemerintahan, item tersebut sangat sulit dibenarkan sebagai kebutuhan operasional wajar dan berisiko menimbulkan kesan penggunaan anggaran yang tidak patut.', NULL, NULL, 4, 1, 1, 1, 1, 2391831);
