INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65861226', 65861226, 'analyze_legacy', 'Kota Batu', 'kabkota', 'Puskesmas Batu', 'Belanja Bahan-Bahan Lainnya - Paket BMHP Lab', 'Barang', 'E-Purchasing', 'Jawa Timur, Batu (Kota)', 12171150, 'March 2026', 'BLUD', 1, 1, '1 Paket', 'Alkohol swab cover glass ukuran 22x22cm kemasan satu satu Eter alkohol 100 ml Kartu Golongan Darah Lidi waten Pipet tetes plastik disposible Serum cup 1,8 ml tutup ulir (cryogenic vial)', '- Alkohol swab sebanyak 100 box : Bahan: Tissue non-woven 2-ply (dua lapis). Kandungan Aktif: Isopropyl Alcohol 70% (atau ethyl alcohol 70%). Fungsi: Antiseptik untuk desinfeksi kulit sebelum suntik, pengambilan darah, pemasangan infus, atau membersihkan permukaan alat medis dan gadget. Kemasan: Sachet aluminium foil kedap udara, steril, dan mudah disobek. Ukuran: Bervariasi, umumnya sekitar 3x3 cm. Pemakaian: Sekali pakai (disposable). - Cover glass ukuran 22x22cm kemasan satu satu sebanyak 1 box : Ketebalan: Sangat tipis, sekitar 0.13mm hingga 0.17mm, untuk transparansi maksimal. Bahan: Kaca optik berkualitas tinggi (seringkali borosilikat). Bentuk: Persegi. Fungsi: Menutup spesimen pada slide mikroskop agar tetap datar, melindungi dari debu, dan membentuk lapisan sampel yang seragam. Kemasan: Biasanya 1 pak berisi 100 buah. - Eter alkohol 100 ml sebanyak 3 botol : cairan pembersih khusus lensa mikroskop dan objek gelas dari minyak imersi, kemasan botol 100 ml, digunakan di laboratorium untuk menjaga kejernihan visual mikroskop. - Kartu Golongan Darah sebanyak 1 pak : bahan: kertas karton tebal atau kertas BC (Blues White). Ukuran: Sekitar 9 cm x 5 cm atau 9 cm x 5.5 cm, mirip ukuran kartu pos atau KTP, agar mudah dipegang. Warna: Seringkali berwarna terang seperti biru tosca atau kuning agar kontras dengan darah dan serum. Fitur: Memiliki bulatan-bulatan cekung atau area khusus untuk menampung darah dan serum reagen agar tidak mudah tumpah. - Lidi waten sebanyak 1 box : bahan batang kayu atau bambu berkualitas, ujungnya dibalut kapas 100% katun yang lembut, bersih, dan steril (bisa disterilkan), dengan panjang bervariasi (biasanya sekitar 15-20 cm) untuk berbagai keperluan medis seperti membersihkan luka atau mengoleskan obat, dikemas dalam jumlah tertentu per pak misalnya 80 pcs/pack atau 100 pcs/pack. - Pipet tetes plastik disposible sebanyak 2 box : Bahan: Plastik transparan (biasanya polietilena/LDPE). Kapasitas/Volume 3 ml terdapat Graduasi (Garis Ukur) skala mililiter. - Serum cup 1,8 ml tutup ulir (cryogenic vial) sebanyak 10 bag : bahan plastik (biasanya polipropilena), sekali pakai, memiliki tutup ulir anti bocor untuk penyimpanan suhu sangat rendah (kriogenik), seringkali ada tanda ukur (graduation), dan desain bagian bawah bisa kerucut atau datar (berdiri sendiri) untuk stabilitas di dalam freezer atau nitrogen cair, sering dilengkapi area label untuk identifikasi sampel.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2395521);
