INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65861609', 65861609, 'analyze_legacy', 'Kota Batu', 'kabkota', 'Puskesmas Batu', 'Belanja Bahan-Bahan Lainnya - Paket Hematologi Micros', 'Barang', 'E-Purchasing', 'Jawa Timur, Batu (Kota)', 43392130, 'March 2026', 'BLUD', 1, 1, '1 Paket', 'ABX Miniclean ABX Minidyl ABX Minilyse ABX Minitrol ABX Minoclair', '- ABX Miniclean sebanyak 4 botol : reagen pembersih profesional untuk diagnosis in vitro di laboratorium, berfungsi untuk pembersih untuk alat analisis hematologi ABX. - ABX Minidyl sebanyak 2 galon : reagen diluent isotonik untuk alat hematologi HORIBA Medical, berfungsi mengencerkan sampel darah untuk penghitungan sel darah (sel darah merah, sel darah putih, trombosit) dan mengukur hematokrit, kemasan 10L - ABX Minilyse sebanyak 1 botol : Reagen lisis untuk menganalisis darah lengkap, khusus untuk penganalisis hematologi. Digunakan Bersama: Peralatan ABX Micros 60 & ES60. Kemasan: 1 Liter (LMG) Penggunaan: Profesional, In-vitro Diagnostics (IVD) di laboratorium. - ABX Minitrol sebanyak 4 vial : Reagen kontrol untuk kalibrasi dan pemeliharaan alat hematologi ABX. Mengandung kontrol untuk parameter darah merah (RBC), hemoglobin (HGB), hematokrit (HCT), MCV, MCH, MCHC, jumlah sel darah putih (WBC), dan diferensial sel (NE, LY, MO, EO, BA). - ABX Minoclair sebanyak 1 botol : larutan pembersih (lysing agent/bleach) khusus untuk penganalisis hematologi otomatis, berfungsi untuk membersihkan jalur sampel dan menjaga akurasi alat, serta dirancang khusus untuk penggunaan diagnosis in vitro profesional di laboratorium medis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2397580);
