INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65865841', 65865841, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693718 BALAI PENEGAKAN HUKUM KEHUTANAN WILAYAH MALUKU PAPUA', 'Konsultan Pengawas Pekerjaan (8% dari Anggaran Pekerjaan)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Papua Barat Daya, Sorong (Kota)', 32000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '( 1, KEG, @ 32000000 )', '1. Konsultan Pengawas Pekerjaan (8% dari Anggaran Pekerjaan) ( 1, KEG, @ 32000000 );', 'Konsultan Pengawas Pekerjaan Pembuatan Pagar merupakan kegiatan pengawasan teknis dan administratif yang dilaksanakan untuk memastikan seluruh tahapan pembangunan pagar berjalan sesuai dengan dokumen kontrak, gambar kerja, rencana anggaran biaya (RAB), serta spesifikasi teknis yang telah ditetapkan. Kegiatan ini dialokasikan sebesar 8% dari nilai anggaran pekerjaan atau sebesar Rp32.000.000 untuk 1 (satu) kegiatan pengawasan sampai dengan selesainya pekerjaan dan dilaksanakannya serah terima pertama (PHO). Dalam pelaksanaannya, konsultan pengawas bertanggung jawab melakukan penelaahan awal terhadap dokumen perencanaan sebelum pekerjaan dimulai, termasuk memverifikasi kesesuaian gambar, spesifikasi teknis, dan metode pelaksanaan. Pada tahap pekerjaan persiapan, pengawas memastikan kegiatan pengukuran, penentuan titik pagar, dan pembersihan lokasi telah sesuai dengan rencana. Selanjutnya, pengawasan dilakukan secara menyeluruh terhadap pekerjaan struktur, mulai dari galian dan pondasi, pemasangan lantai kerja, pekerjaan pondasi batu kali atau beton bertulang, hingga pelaksanaan kolom atau tiang pagar sesuai desain. Pengawas juga memastikan pemasangan panel pagar, baik berupa besi hollow, wiremesh, pagar tembok, maupun kombinasi material lainnya, dilaksanakan sesuai standar mutu dan ketentuan teknis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2399816);
